# Generated by Descant: acceptance tests.

require "timekeeping_relay"

RSpec.describe TimekeepingRelay::FailureReason do
  # "No token is written to a payload or a log line."
  # Only the contract's own error names may pass through; any other text a
  # consumer sends back is replaced, so it can never be copied into a log.
  it "maps a response reason that carries a credential and a newline to unrecognized" do
    token = "service-relay-secret-token"
    hostile = TimekeepingRelay::Response.new(status: 401, body: { "reason" => "Bearer #{token}\nINFO forged line" })
    stale = TimekeepingRelay::Response.new(status: 409, body: { "reason" => "stale_generation" })

    expect(described_class.for(hostile)).to eq("unrecognized")
    expect(described_class.for(stale)).to eq("stale_generation")
  end
end
